alt:
package main

import (
	"fmt"
	"strconv"
)

func FizzBuzz(n int) string {
	s := ""
	if n%3 == 0 {
		s += "Fizz"
	}
	if n%5 == 0 {
		s += "Buzz"
	}
	if s == "" {
		s = strconv.Itoa(n)
	}
	return s
}

func main() {
	for i := 1; i <= 15; i++ {
		fmt.Println(FizzBuzz(i))
	}
}
